import json
for fn in ['hff4dn.json','h1_4dn.json']:
 d=json.load(open('/workspace/'+fn))
 print(fn, d.keys())
 for k,v in d.items():
  if isinstance(v,list): print(' ',k,len(v))
 pf=d.get('processed_files',[])
 print('processed_files',len(pf))
 for x in pf:
  print(x.get('accession'), x.get('file_type'), x.get('file_type_detailed'), x.get('display_title'), x.get('file_size'), x.get('open_data_url'))
PY"

